package api

import "testing"

func TestBulkReassignIsAtomicOnMissingTicket(t *testing.T) {
	srv := startServer(t)
	defer srv.Close()

	fromAgent := doRequest(t, srv.URL, "POST", "/api/agents", map[string]any{"name": "A", "email": "a@example.com"})
	toAgent := doRequest(t, srv.URL, "POST", "/api/agents", map[string]any{"name": "B", "email": "b@example.com"})
	fromID := fromAgent.body["id"]

	ticket1 := doRequest(t, srv.URL, "POST", "/api/tickets", map[string]any{"subject": "A", "agentId": fromID})
	t1ID := jsonNum(ticket1.body["id"])

	resp := doRequest(t, srv.URL, "POST", "/api/tickets/bulk-reassign", map[string]any{
		"toAgentId": toAgent.body["id"],
		"ticketIds": []any{ticket1.body["id"], 999999},
	})
	if resp.status != 404 {
		t.Fatalf("expected 404, got %d", resp.status)
	}

	check := doRequest(t, srv.URL, "GET", "/api/tickets/"+t1ID, nil)
	if jsonNum(check.body["agentId"]) != jsonNum(fromID) {
		t.Fatalf("expected ticket to remain with source agent, got agentId %v", check.body["agentId"])
	}
}

func TestBulkReassignRespectsDestinationCapacity(t *testing.T) {
	srv := startServer(t)
	defer srv.Close()

	fromAgent := doRequest(t, srv.URL, "POST", "/api/agents", map[string]any{"name": "A", "email": "a@example.com"})
	cap := 1
	toAgent := doRequest(t, srv.URL, "POST", "/api/agents", map[string]any{
		"name": "B", "email": "b@example.com", "maxOpenTickets": cap,
	})
	fromID := fromAgent.body["id"]

	ticket1 := doRequest(t, srv.URL, "POST", "/api/tickets", map[string]any{"subject": "A", "agentId": fromID})
	ticket2 := doRequest(t, srv.URL, "POST", "/api/tickets", map[string]any{"subject": "B", "agentId": fromID})

	resp := doRequest(t, srv.URL, "POST", "/api/tickets/bulk-reassign", map[string]any{
		"toAgentId": toAgent.body["id"],
		"ticketIds": []any{ticket1.body["id"], ticket2.body["id"]},
	})
	if resp.status != 400 {
		t.Fatalf("expected 400 (2 tickets exceed destination cap 1), got %d", resp.status)
	}
}

