		c.JSON(http.StatusBadRequest, gin.H{"error": "maxOpenTickets must be a positive integer"})
		return
	}
	agent := store.CreateAgent(name, email, body.MaxOpenTickets)
	c.JSON(http.StatusCreated, agent)
}

func listAgents(c *gin.Context) {
	c.JSON(http.StatusOK, store.ListAgents())
}

